// Content with portions generated by generative AI platform
package org.eclipse.kura.core.token.jwt.issuer;

import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;

import org.eclipse.kura.core.testutil.pki.TestCA.TestCAException;
import org.eclipse.kura.core.token.jwt.common.AbstractJwtScenario;
import org.eclipse.kura.core.token.jwt.common.IssuingConfig;
import org.eclipse.kura.core.token.jwt.common.TokenInspector;
import org.eclipse.kura.security.token.TokenIssueRequest;
import org.junit.Test;

public class TokenIdentifierTest extends AbstractJwtScenario {

    private String firstTokenId;
    private String secondTokenId;

    @Test
    public void everyIssuedTokenCarriesATokenIdentifier() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsIssuedFor(TEST_IDENTITY);

        thenIssuedTokenClaimIsAUniversallyUniqueIdentifier("jti");
    }

    @Test
    public void twoTokensIssuedFromTheSameRequestCarryDifferentTokenIdentifiers() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenTheSameRequestIsIssuedTwice();

        thenBothTokensCarryATokenIdentifier();
        thenTheTwoTokenIdentifiersDiffer();
    }

    private void givenAnIssuerWithASigningKey() throws TestCAException {
        givenKeystorePrivateKeyEntry(SIGNING_ALIAS, 0);
        givenTheIssuerIsBoundToTheKeystore();
        givenTheIssuerIsActivatedWith(IssuingConfig.defaults().withSigningKeyAlias(SIGNING_ALIAS));
    }

    private void whenTheSameRequestIsIssuedTwice() {
        final TokenIssueRequest request = TokenIssueRequest.builder(TEST_IDENTITY).build();

        whenATokenIsIssued(request);
        this.firstTokenId = tokenIdOfIssuedToken();

        whenATokenIsIssued(request);
        this.secondTokenId = tokenIdOfIssuedToken();
    }

    private void thenBothTokensCarryATokenIdentifier() {
        assertNotNull("the first token carries no jti claim", this.firstTokenId);
        assertNotNull("the second token carries no jti claim", this.secondTokenId);
    }

    private void thenTheTwoTokenIdentifiersDiffer() {
        assertNotEquals("two issued tokens share the same jti claim", this.firstTokenId, this.secondTokenId);
    }

    private String tokenIdOfIssuedToken() {
        thenATokenIsIssued();

        return TokenInspector.of(issuedToken()).claim("jti").map(claim -> claim.getAsString()).orElse(null);
    }

}
